#!/usr/bin/env python
"""Django's command-line utility for administrative tasks."""

import importlib.util
import os
import sys

from family_scheduler.utils.observability import instrument_runtime_dependencies

OTEL_AVAILABLE = (
    importlib.util.find_spec("opentelemetry.instrumentation.django") is not None
)


def instrument_management_runtime() -> None:
    instrument_runtime_dependencies(
        include_django=True,
        excluded_urls="/metrics,/health,/healthz",
    )


def main():
    """Run administrative tasks."""
    os.environ.setdefault("DJANGO_SETTINGS_MODULE", "family_scheduler.settings")

    # Enable rich tracebacks in development only
    debug = os.environ.get("DEBUG", "True").lower() == "true"
    if debug:
        try:
            from rich.traceback import install

            install(show_locals=True, suppress=["site-packages"])
        except ImportError:
            pass

    if OTEL_AVAILABLE:
        instrument_management_runtime()

    try:
        from django.core.management import execute_from_command_line
    except ImportError as exc:
        raise ImportError(
            "Couldn't import Django. Are you sure it's installed and "
            "available on your PYTHONPATH environment variable? Did you "
            "forget to activate a virtual environment?"
        ) from exc
    execute_from_command_line(sys.argv)


if __name__ == "__main__":
    main()

